import React from 'react';import {createRoot}from'react-dom/client';import {PackageControl}from'../../app/package-control';
const products=[{sku:'fillerday',name:'Day Cream'},{sku:'fillernight',name:'Night Cream'},{sku:'trialeyecream trialbodycream trialnewfoundation',name:'Trial Pack (GWP)'}];
(window as any).posts=[];(window as any).searches=[];
window.fetch=async(url,init)=>{let data:any;if(String(url).includes('/api/inventory-skus')){(window as any).searches.push(String(url));if((window as any).failSearch)return new Response(JSON.stringify({error:'Search unavailable'}),{status:503});const params=new URL(String(url),location.origin).searchParams,q=(params.get('q')??'').toLowerCase();data={products:products.filter(p=>params.has('sku')?p.sku.toLowerCase()===params.get('sku')?.trim().toLowerCase()||p.name.toLowerCase()===params.get('name')?.trim().toLowerCase():(p.sku+' '+p.name).toLowerCase().includes(q)),canEdit:true};}else if(init?.method==='POST'){const body=JSON.parse(String(init.body));(window as any).posts.push(body);data={ok:true,packageId:body.clientRequestId,status:'draft',sheetSyncStatus:'not_sent'};}else data={packages:[],source:'database',canDelete:false,environment:'staging'};return new Response(JSON.stringify(data),{headers:{'Content-Type':'application/json'}});};
createRoot(document.getElementById('root')!).render(<PackageControl storeId="shopee-berlanco-beauty-official" storeName="Berlanco Beauty Official" staging standaloneCreate prefills={[{requestId:1,name:"Catalog Test",sellingPrice:100,calculatorSettings:{source:"Shopee Pricing Calculator",packageName:"Catalog Test",serviceScenario:"Non-Campaign Day",facebookPrice:100,suggestedShopeePrice:100,commissionRate:0,serviceRate:0,actualPayout:100,category:"Beauty"} as any}]}/>);
